(function(){
  'use strict';
  const data=window.ImagingAtlas,model=window.ImagingAtlasModel;
  const assets=new Map([...window.ImagingAssets,...window.ImagingAtlasMedia].map(a=>[a.id,a]));
  const base='/academia/ebook/imagenes-respiratorias/images/';
  const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const asset=id=>assets.get(id);
  const src=id=>base+(asset(id).poster||asset(id).file);
  const credit=id=>{const a=asset(id);return `<a href="${esc(a.source)}" target="_blank" rel="noreferrer">Original</a> · ${esc(a.author)} · <a href="${esc(a.licenseUrl||a.source)}" target="_blank" rel="noreferrer">${esc(a.license)}</a>`;};
  const figure=(id,title,extra='')=>`<figure class="atlas-figure"><button type="button" class="atlas-enlarge" data-atlas-enlarge="${id}" aria-label="Ampliar ${esc(title)}"><img loading="lazy" src="${src(id)}" alt="${esc(title)}">${extra}</button><figcaption>${esc(title)}<small>${credit(id)}</small></figcaption></figure>`;
  const modal=document.querySelector('#atlas-dialog');
  document.addEventListener('click',event=>{const b=event.target.closest('[data-atlas-enlarge]');if(!b)return;const a=asset(b.dataset.atlasEnlarge);modal.querySelector('img').src=src(a.id);modal.querySelector('img').alt=b.getAttribute('aria-label');modal.querySelector('.atlas-dialog-credit').innerHTML=credit(a.id);modal.showModal();});
  modal.querySelector('button').addEventListener('click',()=>modal.close());
  const panel=document.querySelector('#clinical-atlas');
  let selected='normal-pa',filter='all',marks=false,comparison=false;
  panel.innerHTML='<div class="atlas-toolbar"><label>Estudio<select data-atlas-filter><option value="all">Todos · normal primero</option><option value="rx">RX frontal</option><option value="lat">RX lateral</option><option value="ct">TC / angio-TC</option><option value="eco">Ecografía</option></select></label><button type="button" data-atlas-action="marks" aria-pressed="false">Mostrar marcas educativas</button><button type="button" data-atlas-action="compare" aria-pressed="false">Comparar con referencia normal</button></div><div class="atlas-feature"></div><p class="small">Elegí una miniatura. Las imágenes provienen de distintos pacientes; no representan una evolución individual. Algunas conservan flechas o círculos originales que no se ocultan con el botón de marcas.</p><div class="atlas-thumbnails"></div>';
  function paintAtlas(){
    const c=model.card(selected),regions=c.regions.map(([x,y,rx,ry,label],i)=>`<g><ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${ry}"/><text x="${x}" y="${y}">${i+1}</text></g>`).join('');
    const overlay=marks?`<svg class="atlas-marks" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">${regions}</svg>`:'';
    let reference={rx:'rx-pa-pareada',lat:'rx-lateral-normal',ct:'ct-normal-55',eco:'eco-video-1'}[c.modality];
    if(c.id==='bronquiectasias')reference='ct-coronal-34';
    const sameAsReference=reference===c.asset;const showReference=comparison&&!sameAsReference;panel.querySelector('.atlas-feature').innerHTML=`<div class="atlas-main-images ${showReference?'is-comparing':''}">${figure(c.asset,c.title,overlay)}${showReference?figure(reference,'Referencia normal · comparación orientativa'):''}</div><aside class="atlas-explanation" aria-live="polite"><span class="pill">${c.normal?'NORMALIDAD PRIMERO':'IMAGEN CLÍNICA PUBLICADA'}</span><h3>${esc(c.title)}</h3><p><strong>Qué mirar:</strong> ${esc(c.finding)}</p><p><strong>Qué no concluye:</strong> ${esc(c.limit)}</p>${marks?`<p class="atlas-mark-guide">${c.regions.length?c.regions.map((r,i)=>`${i+1}. ${esc(r[4])}`).join(' · '):'Este caso no tiene marcas nuevas. Se conserva el archivo publicado sin inventar contornos.'}</p>`:''}<p class="small">Marcas orientativas, no segmentación ni mediciones clínicas.</p>${comparison&&sameAsReference?'<p class="small">Esta imagen es la referencia normal de su modalidad: elegí una miniatura con hallazgo para compararla con ella.</p>':''}${showReference?'<p class="small">No es un antes/después. Técnica, orientación, nivel anatómico y paciente pueden diferir. La ecografía compara un fotograma: para valorar movimiento usá los videos.</p>':''}<a href="#${c.reference}">Referencia de lectura →</a></aside>`;
    panel.querySelector('.atlas-thumbnails').innerHTML=model.filter(filter).map(c=>`<button type="button" data-atlas-card="${c.id}" aria-pressed="${c.id===selected}"><img loading="lazy" src="${src(c.asset)}" alt=""><span>${esc(c.title)}</span></button>`).join('');
    panel.querySelector('[data-atlas-action="marks"]').setAttribute('aria-pressed',String(marks));
    panel.querySelector('[data-atlas-action="compare"]').setAttribute('aria-pressed',String(comparison));
  }
  panel.addEventListener('change',event=>{if(event.target.matches('[data-atlas-filter]')){filter=event.target.value;selected=model.filter(filter)[0].id;marks=false;paintAtlas();}});
  panel.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.atlasCard){selected=b.dataset.atlasCard;marks=false;paintAtlas();panel.querySelector(`[data-atlas-card="${selected}"]`).focus({preventScroll:true});panel.querySelector('.atlas-feature').scrollIntoView({block:'start',behavior:'instant'});}else if(b.dataset.atlasAction){if(b.dataset.atlasAction==='marks')marks=!marks;else comparison=!comparison;paintAtlas();}});
  paintAtlas();
  const stack=document.querySelector('#ct-multiplanar');
  let plane='axial',index=4;
  stack.innerHTML='<div class="atlas-toolbar"><label>Plano<select data-plane><option value="axial">Axial · superior a inferior</option><option value="coronal">Coronal · recorrido de la serie publicada</option><option value="sagittal">Sagital · recorrido de la serie publicada</option></select></label><button type="button" data-frame-step="-1">← Anterior</button><button type="button" data-frame-step="1">Siguiente →</button></div><div class="ct-three-plan"><div class="ct-active-frame"></div><aside><h3>Orientarse antes de interpretar</h3><p><strong>Axial:</strong> corte transversal. La derecha del paciente aparece a la izquierda del observador.</p><p><strong>Coronal:</strong> corte frontal. Seguí la continuidad vertical de pulmones, bronquios y diafragmas.</p><p><strong>Sagital:</strong> perfil. Relacioná esternón, corazón, columna y diafragma.</p><p>Confirmá orientación en los marcadores originales. Los planos se navegan por separado: no hay coordenadas sincronizadas ni reconstrucción DICOM.</p><p class="small">Selección no continua: 9 axiales, 11 coronales y 11 sagitales. El número original identifica la captura, no una distancia ni una medición.</p></aside></div><label class="ct-slider">Recorrer capturas<input type="range" data-ct-frame min="0" value="4" step="1"></label><p class="ct-frame-status" role="status"></p>';
  function paintFrame(){const series=data.planes[plane];index=model.frame(index,series.length);const id=series[index];stack.querySelector('.ct-active-frame').innerHTML=figure(id,`TC normal · ${plane} · captura ${index+1} de ${series.length}`);const slider=stack.querySelector('[data-ct-frame]');slider.max=series.length-1;slider.value=index;stack.querySelector('[data-frame-step="-1"]').disabled=index===0;stack.querySelector('[data-frame-step="1"]').disabled=index===series.length-1;stack.querySelector('.ct-frame-status').textContent=`${plane} · ${index+1}/${series.length} · archivo original ${asset(id).title}.`;}
  stack.addEventListener('change',e=>{if(e.target.matches('[data-plane]')){plane=e.target.value;index=Math.floor(data.planes[plane].length/2);paintFrame();}});
  stack.addEventListener('input',e=>{if(e.target.matches('[data-ct-frame]')){index=Number(e.target.value);paintFrame();}});
  stack.addEventListener('click',e=>{const b=e.target.closest('[data-frame-step]');if(b){index+=Number(b.dataset.frameStep);paintFrame();}});
  paintFrame();
  function videoCard(v){const a=asset(v.asset);return `<article class="clinical-video"><h3>${esc(v.title)}</h3><video controls playsinline muted preload="none" poster="${src(v.asset)}" aria-label="${esc(v.title)}"><source src="${base+a.file}" type="video/webm">Tu navegador no admite este video. Consultá el archivo original enlazado debajo.</video><div class="video-tools"><button type="button" data-video-play>Reproducir</button><label>Velocidad<select data-video-speed><option value="0.5">0,5× · lento</option><option value="1" selected>1× · original</option></select></label></div><p class="video-error" role="status" hidden>No se pudo reproducir el archivo. Probá un navegador compatible con WebM o consultá el original.</p><p><strong>Descripción visual:</strong> ${esc(v.description)}</p><p><strong>Límite:</strong> ${esc(v.limit)}</p><p class="small">${credit(v.asset)}. Sin edición local.</p></article>`;}
  document.querySelector('#lung-video-gallery').innerHTML=data.videos.map(videoCard).join('');
  document.querySelector('#ct-window-videos').innerHTML=[{asset:'ct-video-pulmon',title:'Reconstrucción coronal · pulmón',description:'Recorrido publicado con reconstrucción para pulmón. Compará la trama y los límites de las regiones aireadas.',limit:'Ejemplo técnico: no se presenta como certificado de normalidad ni como estudio del mismo paciente del atlas multiplanar.'},{asset:'ct-video-mediastino',title:'Reconstrucción coronal · mediastino',description:'Recorrido publicado para tejidos blandos del mismo autor y adquisición descrita. Observá cómo cambia la representación del centro del tórax.',limit:'Son videos exportados con diferentes reconstrucciones, no un ajuste de ventana interactivo. No están sincronizados corte a corte.'}].map(videoCard).join('');
  document.querySelectorAll('.clinical-video').forEach(card=>{const video=card.querySelector('video'),button=card.querySelector('[data-video-play]');button.addEventListener('click',()=>{if(video.paused)video.play().catch(error=>{if(error&&error.name==='AbortError')return;card.querySelector('.video-error').hidden=false;});else video.pause();});card.querySelector('[data-video-speed]').addEventListener('change',e=>{video.playbackRate=Number(e.target.value);});video.addEventListener('play',()=>{document.querySelectorAll('.clinical-video video').forEach(other=>{if(other!==video)other.pause();});button.textContent='Pausar';card.querySelector('.video-error').hidden=true;});video.addEventListener('pause',()=>{button.textContent='Reproducir';});video.addEventListener('ended',()=>{button.textContent='Reproducir';});video.addEventListener('error',()=>{card.querySelector('.video-error').hidden=false;});});
  document.addEventListener('visibilitychange',()=>{if(document.hidden)document.querySelectorAll('.clinical-video video').forEach(v=>v.pause());});
  const quiz=document.querySelector('#visual-assessment');
  quiz.innerHTML=`<div class="assessment-cases">${data.exam.map((q,i)=>`<fieldset class="visual-question"><legend>${i+1}. ${esc(q.context)}</legend><img loading="lazy" src="${src(q.asset)}" alt="Imagen clínica de referencia del ejercicio ${i+1}; interpretar junto con la pregunta"><div><h3>${esc(q.prompt)}</h3>${q.choices.map(c=>`<label class="answer"><input type="radio" name="${q.id}" value="${c.id}"><span>${esc(c.text)}</span></label>`).join('')}<div class="question-review" hidden></div></div></fieldset>`).join('')}</div><p class="assessment-progress" role="status">0 de ${data.exam.length} respondidas</p><div class="actions"><button type="button" class="button" data-grade disabled>Corregir evaluación</button><button type="button" class="button secondary" data-exam-reset>Reiniciar evaluación</button></div><div class="assessment-result" role="status" hidden></div>`;
  const answers=()=>Object.fromEntries([...quiz.querySelectorAll('input:checked')].map(i=>[i.name,i.value]));
  function clearReview(){quiz.querySelectorAll('.question-review').forEach(el=>{el.hidden=true;});quiz.querySelector('.assessment-result').hidden=true;}
  quiz.addEventListener('change',()=>{const a=answers();clearReview();quiz.querySelector('[data-grade]').disabled=model.grade(a)===null;quiz.querySelector('.assessment-progress').textContent=`${Object.keys(a).length} de ${data.exam.length} respondidas`;});
  quiz.querySelector('[data-grade]').addEventListener('click',()=>{const a=answers(),result=model.grade(a);if(!result)return;quiz.querySelectorAll('.question-review').forEach((el,i)=>{const q=data.exam[i];el.hidden=false;el.innerHTML=`<strong>${result.results[i].correct?'✓ Correcta':'Revisar respuesta'}</strong><p>${esc(q.explanation)}</p><p>${credit(q.asset)} · <a href="#${q.reference}">Referencia clínica</a></p>`;});const output=quiz.querySelector('.assessment-result');output.hidden=false;output.textContent=`${result.correct} de ${result.total} correctas. Revisá la explicación de cada caso. Es una autoevaluación educativa, no certificación de competencia clínica.`;output.scrollIntoView({block:'center',behavior:'instant'});});
  quiz.querySelector('[data-exam-reset]').addEventListener('click',()=>{quiz.querySelectorAll('input').forEach(i=>{i.checked=false;});clearReview();quiz.querySelector('[data-grade]').disabled=true;quiz.querySelector('.assessment-progress').textContent=`0 de ${data.exam.length} respondidas`;});
  document.querySelector('#atlas-credits').innerHTML=window.ImagingAtlasMedia.map(a=>`<li><strong>${esc(a.id)}</strong> · ${credit(a.id)}. ${esc(a.modifications)}</li>`).join('');
  document.querySelectorAll('#clinical-atlas img, #ct-multiplanar img, #visual-assessment img').forEach(img=>img.addEventListener('error',()=>{img.alt+=' · Archivo no disponible: consultar original.';}));
})();
